                const y = -index * 10;

                return (
                    <motion.span
                        key={index}
                        className="h-[70px] w-[100px] absolute rounded-full"
                        style={{
                            x,
                            y,
                            zIndex: numberOfCubes - index,
                            backgroundColor: colors[index % colors.length],
                            opacity: 1 - index * 0.05
                        }}
                        initial={{ scale: 1 }}
                        animate={{ scale: [1, 0.75, 1], rotate: [0, 360] }}
                        transition={{
                            ...transition,
                            delay: index * 0.05
                        }}
                    />
                );
            })}
        </div>
    );
}

