                                {option}
                            </p>

                            {isActive && (
                                <motion.div
                                    layout
                                    layoutId={slug + 'magnet'}
                                    transition={{ duration: 0.2, type: 'spring', bounce: 0.2 }}
                                    className="w-full h-1 absolute bottom-full left-0 bg-blue-500 rounded-sm"
                                />
                            )}

                            {(hovered === option || (hovered === undefined && isActive)) && (
