"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useReducedMotion } from "motion/react";

if (typeof window !== "undefined") gsap.registerPlugin(ScrollTrigger);

const SCALE_OFFSCREEN = 1.2;
const ROTATION_DEG = 6;
const SCALE_CENTER = 1.0;
/** @param {{images?: string[], bgColor?: string, scroller?: HTMLElement | import('react').RefObject<HTMLElement | null>, viewportHeight?: string,
 * frameWidth?: number, frameHeight?: number, thumbnailWidth?: number, thumbnailHeight?: number, className?: string}} props */
export function ParallaxGallery({ images = [], bgColor = "#111111", scroller, viewportHeight = "100vh", frameWidth = 500, frameHeight = 600, thumbnailWidth = 190, thumbnailHeight = 260, className = "" }) {
  const slides = images.map((src, index) => ({ id: `slide-${index}`, src }));
  const total = slides.length;

  const [activeIndex, setActiveIndex] = useState(0);
  const sectionRef = useRef(null);
  const galleryRef = useRef(null);
  const itemInnerRefs = useRef([]);
  const thumbLeftRef = useRef(null);
  const thumbRightRef = useRef(null);

  const reduceMotion = useReducedMotion();
  const frameW = frameWidth;
  const frameH = frameHeight;
  const slideW = frameW;
  const thumbW = thumbnailWidth;
  const thumbH = thumbnailHeight;
  const thumbGap = 12;
  const thumbItem = thumbW + thumbGap;

  const applyPosition = useCallback(
    (pos) => {
      if (!galleryRef.current) return;

      galleryRef.current.style.transform = `translate3d(${-pos * slideW}px, 0px, 0px)`;

      itemInnerRefs.current.forEach((el, index) => {
        if (!el) return;
        const dist = index - pos;
        const absDist = Math.abs(dist);
        const rot = dist > 0 ? Math.min(absDist, 1) * ROTATION_DEG : -Math.min(absDist, 1) * ROTATION_DEG;
        const scale = SCALE_CENTER + Math.min(absDist, 1) * (SCALE_OFFSCREEN - SCALE_CENTER);
        el.style.transform = `rotate(${rot}deg) scale(${scale})`;
      });

      if (thumbLeftRef.current) thumbLeftRef.current.style.transform = `translate3d(${-pos * thumbItem}px, -50%, 0px)`;
      if (thumbRightRef.current) thumbRightRef.current.style.transform = `translate3d(${-(pos + 1) * thumbItem}px, -50%, 0px)`;
      setActiveIndex(Math.max(0, Math.min(total - 1, Math.round(pos))));
    },
    [slideW, thumbItem, total]
  );

  useEffect(() => {
    if (total <= 1 || reduceMotion) return;

    const section = sectionRef.current;
    if (!section) return;

    const snapValues = Array.from({ length: total }, (_, index) => index / (total - 1));
    const st = ScrollTrigger.create({
      trigger: section,
      scroller: scroller?.current !== undefined ? scroller.current : scroller,
      start: "top top",
      end: "bottom bottom",
      snap: {
        snapTo: snapValues,
        duration: { min: 0.2, max: 0.5 },
        ease: "power2.inOut",
        delay: 0,
        inertia: false,
      },
      onUpdate: (self) => applyPosition(self.progress * (total - 1)),
    });

    applyPosition(0);
    return () => st.kill();
  }, [applyPosition, total, reduceMotion, scroller]);

  if (reduceMotion) return <div className={`grid gap-4 p-4 ${className}`} style={{ background: bgColor }}>{images.map((src, index) => <img key={`${src}-${index}`} src={src} alt={`Gallery photograph ${index + 1}`} className="mx-auto h-auto w-full max-w-lg" />)}</div>;

  return (
    <section ref={sectionRef} className={`relative font-body text-white ${className}`} style={{ height: `calc(${viewportHeight} * ${Math.max(total, 1)})`, background: bgColor }}>
      <div className="sticky top-0 w-full select-none overflow-hidden" style={{ background: bgColor, height: viewportHeight }}>
        <div className="absolute" style={{ top: 36, right: 40, fontSize: 11, letterSpacing: "0.22em", textTransform: "uppercase" }}>
          {String(activeIndex + 1).padStart(2, "0")} / {String(total).padStart(2, "0")}
        </div>

        <ThumbStrip refProp={thumbLeftRef} slides={slides} side="left" frameW={frameW} thumbW={thumbW} thumbH={thumbH} thumbGap={thumbGap} bgColor={bgColor} />
        <ThumbStrip refProp={thumbRightRef} slides={slides} side="right" frameW={frameW} thumbW={thumbW} thumbH={thumbH} thumbGap={thumbGap} bgColor={bgColor} />

        <div className="absolute top-1/2 left-1/2" style={{ transform: "translate(-50%, -50%)", zIndex: 20 }}>
          <div className="pointer-events-none absolute top-1/2 left-1/2 z-0 -translate-x-1/2 -translate-y-1/2 border border-dashed border-white/50" style={{ height: frameH + 24, width: frameW + 24 }} />
          <div className="absolute top-1/2 left-1/2 m-auto overflow-hidden" style={{ width: frameW - 10, height: frameH - 10, transform: "translate(-50%, -50%)" }}>
            <div ref={galleryRef} className="absolute top-0 left-0 bottom-0 flex will-change-transform" style={{ width: slideW * total }}>
              {slides.map((slide, index) => (
                <div key={slide.id} className="relative shrink-0 overflow-hidden" style={{ width: slideW, height: frameH }}>
                  <div
                    ref={(el) => { itemInnerRefs.current[index] = el; }}
                    className="absolute inset-0 will-change-transform"
                    style={{
                      transform: `rotate(${index === 0 ? 0 : ROTATION_DEG}deg) scale(${index === 0 ? 1 : SCALE_OFFSCREEN})`,
                      transformOrigin: "center center",
                    }}
                  >
                    <img src={slide.src} alt={slide.id} draggable="false" className="h-full w-full object-cover" />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

function ThumbStrip({ refProp, slides, side, frameW, thumbW, thumbH, thumbGap, bgColor }) {
  return (
    <div
      style={{
        position: "absolute",
        top: "50%",
        zIndex: 10,
        overflow: "hidden",
        background: bgColor,
        ...(side === "left" ? { right: `calc(50% + ${frameW / 2}px)`, left: 0 } : { left: `calc(50% + ${frameW / 2}px)`, right: 0 }),
        height: thumbH,
        transform: "translateY(-50%)",
      }}
    >
      <div
        ref={refProp}
        className="absolute top-1/2 flex will-change-transform"
        style={{
          gap: thumbGap,
          transform: "translate3d(0px, -50%, 0px)",
          left: side === "left" ? "100%" : 0,
          right: "auto",
        }}
      >
        {slides.map((slide, index) => (
          <div key={index} className="relative shrink-0 overflow-hidden" style={{ width: thumbW, height: thumbH }}>
            <img src={slide.src} alt={slide.id} draggable="false" className="h-full w-full object-cover" />
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import Image from 'next/image';
import React, { useEffect, useRef, useState, useMemo } from 'react';
import { motion, useReducedMotion } from 'motion/react';

interface PixelatedCarouselProps {
    pixelSize?: number;
    animationDelayStep?: number;
    images: string[];
    pixelTransitionDuration?: number;
}

export function PixelatedCarousel({
    pixelSize = 100,
    animationDelayStep = 0.02,
    images,
    pixelTransitionDuration = 0.1
}: PixelatedCarouselProps) {
    const [activeImageIndex, setActiveImageIndex] = useState(0);
    const reduceMotion = useReducedMotion();
    const ref = useRef<HTMLDivElement>(null);
    const [grid, setGrid] = useState({ rows: 0, cols: 0, height: 0, width: 0 });
    const isInitialized = grid.rows > 0 && grid.cols > 0;
    const [isFirstCycle, setIsFirstCycle] = useState(true);

    const sizeOfBox = useMemo(() => {
        if (grid.rows === 0 || grid.cols === 0) return { h: 0, w: 0 };
        return { h: grid.height / grid.rows, w: grid.width / grid.cols };
    }, [grid]);

    const shuffledDelays = useMemo(() => {
        const totalBoxes = grid.rows * grid.cols;
        if (totalBoxes === 0) return [];

        const delays = Array.from({ length: totalBoxes }, (_, i) => i * pixelTransitionDuration);
        for (let i = delays.length - 1; i > 0; i--) {
            const j = (i * 31 + 17) % (i + 1);
            [delays[i], delays[j]] = [delays[j], delays[i]];
        }
        return delays;
    }, [grid.rows, grid.cols, pixelTransitionDuration]);

    const boxState = useMemo(() => {
        if (shuffledDelays.length === 0) return [];
        return shuffledDelays.map((delay, index) => {
            const baseShade = 20 - (index * 13 % 20);
            return { delay, color: `rgb(${baseShade}, ${baseShade}, ${baseShade})` };
        });
    }, [shuffledDelays]);

    useEffect(() => {
        const container = ref.current;
        if (!container) return;
        const observer = new ResizeObserver(([entry]) => {
            const { width, height } = entry.contentRect;
            const size = Math.max(1, pixelSize);
            const next = { rows: Math.max(1, Math.floor(height / size)), cols: Math.max(1, Math.floor(width / size)), width, height };
            setGrid((previous) => previous.width === width && previous.height === height && previous.rows === next.rows && previous.cols === next.cols ? previous : next);
        });
        observer.observe(container);
        return () => observer.disconnect();
    }, [pixelSize]);

    useEffect(() => {
        if (!isInitialized || grid.rows === 0 || grid.cols === 0 || reduceMotion || images.length < 2) return;

        const allBoxesBlackTime = animationDelayStep * (grid.rows * grid.cols - 1) + pixelTransitionDuration;

        if (isFirstCycle) {
            const firstTimeout = setTimeout(() => {
                setActiveImageIndex((prev) => (prev + 1) % images.length);
                setIsFirstCycle(false);
            }, allBoxesBlackTime * 1000);
            return () => clearTimeout(firstTimeout);
        } else {
            const id = setInterval(() => {
                setActiveImageIndex((prev) => (prev + 1) % images.length);
            }, allBoxesBlackTime * 1000 * 2);
            return () => clearInterval(id);
        }
    }, [images.length, grid.rows, grid.cols, isInitialized, isFirstCycle, animationDelayStep, pixelTransitionDuration, reduceMotion]);

    const gridElements = useMemo(() => {
        if (!isInitialized || grid.rows === 0 || grid.cols === 0 || reduceMotion) return null;

        return Array.from({ length: grid.rows }).map((_, row) => (
            <span key={row} className="flex">
                {Array.from({ length: grid.cols }).map((_, col) => {
                    const boxIndex = row * grid.cols + col;
                    const box = boxState[boxIndex];
                    if (!box) return null;

                    return (
                        <motion.span
                            key={col}
                            style={{ height: sizeOfBox.h, width: sizeOfBox.w, backgroundColor: box.color }}
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            transition={{
                                duration: pixelTransitionDuration,
                                repeat: Infinity,
                                repeatType: 'reverse',
                                delay: box.delay,
                                repeatDelay: grid.rows * grid.cols * animationDelayStep
                            }}
                        />
                    );
                })}
            </span>
        ));
    }, [isInitialized, grid.rows, grid.cols, boxState, sizeOfBox, pixelTransitionDuration, animationDelayStep, reduceMotion]);

    return (
        <div ref={ref} className="h-full w-full relative">
            {isInitialized && <span className="h-full w-full absolute top-0 left-0 z-10">{gridElements}</span>}
            <div className="h-full w-full z-0 relative">
                {images.map((image, index) => (
                    <Image
                        src={image}
                        key={image + index}
                        alt="pixelated carousel"
                        fill
                        className="object-cover absolute top-0 left-0 h-full w-full"
                        style={{ zIndex: activeImageIndex % images.length === index ? 10 : 0 }}
                    />
                ))}
            </div>
        </div>
    );
}

