import React, { useRef } from 'react'
import { motion, useScroll, useTransform, type MotionStyle } from 'motion/react'
import { cn } from '@/lib/utils'
import '@/components/block/scroll-effect.css'


type ImageProps = {

        start: string[];
        middle: string[];
